+/* Whether another 16-bit word still fits in the eight-word address. */
+static int knownhost_ipv6_room(size_t count)
 {
-    unsigned int value = 0;
-    size_t digits = 0;
-    size_t count = 0;
-
-    while(src < end) {
-        if(*src >= '0' && *src <= '9') {
-            if(digits == 3 || (digits && !value))
-                return 0;
-            value = value * 10 + (unsigned int)(*src - '0');
