-        src++;
-    }
-
-    if(!digits || count != 3)
-        return 0;
-
-    result[3] = (unsigned char)value;
-    return 1;
+    return count < 8;
 }

 static int knownhost_parse_ipv6(const char *src, size_t len,
@@ -442,7 +415,6 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
