-                (unsigned short)(((unsigned int)ipv4[2] << 8) | ipv4[3]);
-            break;
-        }
-
-        if(!digits || count >= 8)
+        if(!digits || !knownhost_ipv6_room(count))
             return 0;

         words[count++] = (unsigned short)value;
@@ -495,7 +454,7 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         size_t position = (size_t)compressed;
         size_t zeros;

-        if(count >= 8)
+        if(!knownhost_ipv6_room(count))
